<script setup>
import { ref,onMounted } from 'vue'
import { api } from '../api'
import { localDate } from '../session'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
const rules=ref({}),editors=ref({}),hosted=ref(null),hostedText=ref(''),monitor=ref(null),error=ref(''),notice=ref(''),writes=useWorkflowWrite('admin-policies')
async function load(){for(const kind of ['mainline','dynamic']){const result=await api.flow('/admin/rules/'+kind);rules.value[kind]=result.items[0]||null;editors.value[kind]=JSON.stringify(result.items[0]?{...result.items[0].payload,enabled:result.items[0].enabled,reason:''}:{enabled:false,approved:false,effective_from:localDate(),tiers:[],rewards:{},fixed_equivalences:{},reason:''},null,2)}hosted.value=await api.flow('/admin/hosted-ai');hostedText.value=JSON.stringify(hosted.value.payload?{...hosted.value.payload,enabled:hosted.value.enabled,reason:''}:{enabled:false,approved:false,provider:'',model:'',secret_ref:'',user_daily_calls:null,global_daily_calls:null,global_daily_tokens:null,daily_cost_cap:null,input_tokens:null,output_tokens:null,input_rate:null,output_rate:null,currency_unit:'',price_checked_on:localDate(),reason:''},null,2);monitor.value=await api.flow('/admin/hosted-monitor')}
async function save(path,value,version){if(writes.busy.value)return;try{await writes.send(path,{...JSON.parse(value),expected_version:version},'PUT');notice.value='配置已保存，当前版本已更新。';await load();error.value=''}catch(e){error.value=e.message}}
onMounted(()=>load().catch(e=>{error.value=e.message}))
</script>
<template><section class="card" id="admin-policies"><h2>条件规则与站点 AI</h2><p class="muted">没有经确认的金额/预算时保持关闭。以下为运营配置，保存不会调用模型或重算历史。</p><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><details v-for="kind in ['mainline','dynamic']" :key="kind"><summary>{{ kind==='mainline'?'主线分档规则':'动态成就奖励规则' }} · {{ rules[kind]?.enabled?'已启用':'未开通' }}</summary><p class="muted">主线启用需完整 tiers、daily_cap、per_fact_cap、max_active、stacking、cap_basis；动态启用需 rewards（语义身份→金额）、user_total_cap、allow_fixed_stack，固定等价项通过 fixed_equivalences 明确登记。approved 须是已获确认的规则。</p><label>版本化规则 JSON<textarea v-model="editors[kind]" rows="14" spellcheck="false"/></label><button class="btn" :disabled="writes.busy.value" @click="save('/admin/rules/'+kind,editors[kind],rules[kind]?.version||0)">保存{{ kind==='mainline'?'主线':'动态' }}规则版本</button></details>
<details><summary>站点默认 AI · {{ hosted?.enabled?'已启用':'未开通' }}</summary><p class="muted">只引用服务器 HOSTED_SECRET_FILE 中的 secret_ref 名称，不读取 owner 私有 Key。input_rate/output_rate 为每百万 Token 的最小费用单位；daily_cost_cap 与 currency_unit 对应，配额日以 UTC 计算。调用前保守预占，未知计费保留预占。</p><label>站点模型与预算 JSON<textarea v-model="hostedText" rows="20" spellcheck="false"/></label><button class="btn" :disabled="writes.busy.value" @click="save('/admin/hosted-ai',hostedText,hosted?.version||0)">保存站点 AI 配置</button></details><details v-if="monitor"><summary>站点 AI 用量监控 · {{ monitor.date_basis }}</summary><p>调用 {{ monitor.calls }} · Token {{ monitor.tokens }} · 费用单位 {{ monitor.cost }}</p><p>结果/计费未确定 {{ monitor.unknown }} · 失败 {{ monitor.failures }}</p><button class="btn" @click="load">重新读取</button></details></section></template>
